// Quote Generator with snapped deductibles (allowed: 100, 250, 500, 1000)

function toInt(v, def = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? Math.trunc(n) : def;
}
function toDate(d) {
  if (!d) return null;
  const dt = new Date(d);
  return isNaN(dt.getTime()) ? null : dt;
}
function calcAge(dob) {
  const today = new Date();
  let age = today.getFullYear() - dob.getFullYear();
  const m = today.getMonth() - dob.getMonth();
  if (m < 0 || (m === 0 && today.getDate() < dob.getDate())) age--;
  return Math.max(0, age);
}
function clamp(x, lo, hi) { return Math.min(hi, Math.max(lo, x)); }
function round2(x) { return Math.round((x + Number.EPSILON) * 100) / 100; }

const allowed = [100, 250, 500, 1000];
const snapUp   = v => allowed.find(x => v <= x) ?? allowed[allowed.length - 1];
const snapDown = v => [...allowed].reverse().find(x => v >= x) ?? allowed[0];

const out = [];
for (const item of items) {
  const j = item.json;

  const dob = toDate(j.date_of_birth);
  const age = dob ? calcAge(dob) : 40;
  const licenseYear = toInt(j.license_issue_year, new Date().getFullYear());
  const yearsLicensed = clamp(new Date().getFullYear() - licenseYear, 0, 80);

  const incidents = toInt(j.incidents, 0);
  const annualMileage = toInt(j.annual_mileage, 12000);
  const desiredDeductible = toInt(j.desired_deductible, 500);

  // Factors (numeric + DOB + license year only)
  const ageF =
    age < 25 ? 1.5 :
    age < 35 ? 1.2 :
    age < 65 ? 1.0 : 1.3;

  const expF =
    yearsLicensed < 3 ? 1.3 :
    yearsLicensed < 10 ? 1.1 : 1.0;

  const incF = 1 + 0.25 * incidents;
  const milF = clamp(1 + ((annualMileage - 12000) / 12000) * 0.2, 0.8, 1.4);
  const dedF = clamp(1 - ((desiredDeductible - 500) / 1000) * 0.1, 0.8, 1.1);

  const base = 600;
  const rawAnnual = base * ageF * expF * incF * milF * dedF;

  // Option B: snap deductibles to allowed set
  const tiers = [
    // Bronze: bump up to next higher allowed, but at least 500
    { tier: 'Bronze', tierMult: 0.90, tierDeductible: snapUp(Math.max(desiredDeductible, 500)) },
    // Silver: nearest allowed at/above desired
    { tier: 'Silver', tierMult: 1.00, tierDeductible: snapUp(desiredDeductible) },
    // Gold: nearest allowed at/below desired, floor at 250
    { tier: 'Gold',   tierMult: 1.15, tierDeductible: snapDown(Math.min(desiredDeductible, 250)) },
  ];

  for (const t of tiers) {
    const annualPremium = rawAnnual * t.tierMult;
    out.push({
      json: {
        session_id: j.session_id,
        cust_name: j.cust_name,
        cust_email: j.cust_email,
        cust_phone: j.cust_phone,

        date_of_birth: j.date_of_birth,
        license_issue_year: licenseYear,
        incidents,
        annual_mileage: annualMileage,
        desired_deductible: desiredDeductible,

        driver_age: age,
        years_licensed: yearsLicensed,
        factors: { ageF, expF, incF, milF, dedF },

        tier: t.tier,
        annual_premium: round2(annualPremium),
        monthly_premium: round2(annualPremium / 12),
        quote_deductible: t.tierDeductible,
      },
    });
  }
}

return out;

// Expect 3 incoming items (Bronze, Silver, Gold) from the previous Code node.
// Output: 1 item containing only premium-related data, ready for a form.

function round2(x) {
  return Math.round((Number(x) + Number.EPSILON) * 100) / 100;
}

// Collect by tier
const tierMap = {};
for (const it of items) {
  const j = it.json || {};
  const tier = String(j.tier || '').trim();
  if (!tier) continue;
  tierMap[tier] = {
    tier,
    annual_premium: round2(j.annual_premium),
    monthly_premium: round2(j.monthly_premium),
    quote_deductible: Number(j.quote_deductible),
  };
}

// Validate presence of all tiers
const required = ['Bronze', 'Silver', 'Gold'];
const missing = required.filter(t => !tierMap[t]);
if (missing.length) {
  throw new Error(
    `Expected 3 quote items (Bronze, Silver, Gold) but missing: ${missing.join(', ')}. ` +
    `Tiers seen: ${Object.keys(tierMap).join(', ') || 'none'}. ` +
    `Check the connection from the previous Code node so all three items reach this node.`
  );
}

// Build ordered array
const quotes = required.map(t => tierMap[t]);

// Build options for a selection form (dropdown)
const selection_options = quotes.map(q => ({
  label: `${q.tier} — $${q.monthly_premium}/mo (deductible ${q.quote_deductible})`,
  value: q.tier,
}));

// Optional summary text for chat/email preview
const summary_text = quotes
  .map(q => `${q.tier}: $${q.monthly_premium}/mo ($${q.annual_premium}/yr), deductible ${q.quote_deductible}`)
  .join(' | ');

// Return a single consolidated item (premium-only fields)
return [{ json: { quotes, selection_options, summary_text } }];

// Goal: set quote_selected to the full premiums line (unparsed).
// Handles these shapes:
// 1) "Premiums Quotes": "<string>"
// 2) "Premiums Quotes": ["<string>", ...]
// 3) "Premiums Quotes": [{label:"...", value:"..."}, ...]
// 4) Any key that contains "premium" or "quote" (case-insensitive) with a suitable string/array value.
// Never falls back to submittedAt. Ignores session_id.

const j = items[0]?.json ?? {};

function isIsoDateString(s) {
  // Don't mistakenly pick timestamps
  return typeof s === 'string' && /^\d{4}-\d{2}-\d{2}T/.test(s);
}

function firstNonEmptyString(arr) {
  for (const v of arr) {
    if (typeof v === 'string' && v.trim() && !isIsoDateString(v)) return v.trim();
    if (v && typeof v === 'object') {
      // common shapes from form components
      if (typeof v.label === 'string' && v.label.trim() && !isIsoDateString(v.label)) return v.label.trim();
      if (typeof v.value === 'string' && v.value.trim() && !isIsoDateString(v.value)) return v.value.trim();
      // try joining known fields if both exist
      const combo = [v.tier, v.text, v.name].filter(Boolean).join(' ');
      if (combo && !isIsoDateString(combo)) return String(combo).trim();
    }
  }
  return '';
}

function pickPremiumLine(obj) {
  // prefer exact keys first
  const exactKeys = ['Premiums Quotes[0]', 'Premiums Quotes'];
  for (const k of exactKeys) {
    if (k in obj) {
      const v = obj[k];
      if (typeof v === 'string' && v.trim() && !isIsoDateString(v)) return v.trim();
      if (Array.isArray(v)) {
        const s = firstNonEmptyString(v);
        if (s) return s;
      }
      if (v && typeof v === 'object') {
        // single object case
        const cand = firstNonEmptyString([v]);
        if (cand) return cand;
      }
    }
  }

  // then try fuzzy match on keys containing "premium" or "quote"
  for (const [k, v] of Object.entries(obj)) {
    const lk = k.toLowerCase();
    if (lk.includes('premium') || lk.includes('quote')) {
      if (typeof v === 'string' && v.trim() && !isIsoDateString(v)) return v.trim();
      if (Array.isArray(v)) {
        const s = firstNonEmptyString(v);
        if (s) return s;
      }
      if (v && typeof v === 'object') {
        const s = firstNonEmptyString([v]);
        if (s) return s;
      }
    }
  }

  // last resort: scan any string value that looks like a premium line but is NOT a timestamp
  for (const v of Object.values(obj)) {
    if (typeof v === 'string' && v.trim() && !isIsoDateString(v) && /Annual\s*Pre(?:mi|im)um/i.test(v)) {
      return v.trim();
    }
  }

  return '';
}

const line = pickPremiumLine(j);

return [
  {
    json: {
      quote_selected: line,                         // may be "" if nothing matched
      submittedAt: typeof j.submittedAt === 'string' ? j.submittedAt : null
    }
  }
];

/**
 * n8n Function node
 * Input: items with fields like in "Normalize-2"
 * Output: cleaned + normalized fields
 */
return items.map(item => {
  const j = item.json ?? {};

  // ---- helpers ----
  const cleanText = (val) => String(val ?? '')
    // real line breaks (CR, LF), Unicode LS/PS, NEL
    .replace(/[\u000a\u000d\u0085\u2028\u2029]+/g, ' ')
    // any number of backslashes before n/t/r/f/v -> space (handles \n, \\n, \\\n, \t, etc.)
    .replace(/\\+[ntrfv]/gi, ' ')
    // redundant: catch stray sequences
    .replace(/\\r|\\t|\\f|\\v/gi, ' ')
    // collapse spaces
    .replace(/\s{2,}/g, ' ')
    .trim();

  const toNumberString = (val, fallback = '0') => {
    // handles "1\n", "0.9", 0.75, etc.
    const n = (typeof val === 'string') ? parseFloat(val) : Number(val);
    if (!Number.isFinite(n)) return fallback;
    // keep minimal string (e.g., "0.9", "1", "0.75")
    return String(n).replace(/\.0+$/,'');
  };

  const toBooleanString = (val) => {
    if (typeof val === 'boolean') return val ? 'true' : 'false';
    const s = cleanText(val).toLowerCase();
    return (['true','1','yes','y'].includes(s)) ? 'true' : 'false';
  };

  // ---- normalized outputs ----
  const normalized = {
    // cleaned free-text
    answer: cleanText(j.answer),
    category: cleanText(j.category),

    // coerced primitives -> string forms you’ve been using downstream
    confidence: toNumberString(j.confidence, '0'),
    needs_escalation: toBooleanString(j.needs_escalation),

    // pass-throughs untouched
    session_id: j.session_id,
    chatInput: j.chatInput,
    execution_id: j.execution_id,

    // (optional) keep originals for debugging/comparison
    _raw: {
      answer: j.answer,
      category: j.category,
      confidence: j.confidence,
      needs_escalation: j.needs_escalation,
    }
  };

  return { json: normalized };
});
